custom_css:
/* ============================================================
   花落 · FALLING BLOSSOMS — мягкий старый Китай
   Свиток в парчовом обрамлении: ответы персонажа — листы
   рисовой бумаги с уголками хуэйвэнь, по ним летят лепестки
   сливы. Пока персонаж отвечает, в поле ввода кисть
   выводит мазок тушью.
   Шрифт Lora (SIL OFL 1.1) встроен в тему.
   Нужен Advanced Rendering.
   ============================================================ */

@font-face {
  font-family: "Lora";
  font-style: normal;
  font-weight: 400 700;
  font-display: swap;
  src: url("theme/assets/lora-normal-cyrillic.woff2") format("woff2");
  unicode-range: U+0301, U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116;
}
@font-face {
  font-family: "Lora";
  font-style: normal;
  font-weight: 400 700;
  font-display: swap;
  src: url("theme/assets/lora-normal-latin.woff2") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}
@font-face {
  font-family: "Lora";
  font-style: italic;
  font-weight: 400 700;
  font-display: swap;
  src: url("theme/assets/lora-italic-cyrillic.woff2") format("woff2");
  unicode-range: U+0301, U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116;
}
@font-face {
  font-family: "Lora";
  font-style: italic;
  font-weight: 400 700;
  font-display: swap;
  src: url("theme/assets/lora-italic-latin.woff2") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}

/* ---------- Анимации ---------- */

/* Лепестки медленно опадают и сносятся ветром */
@keyframes blossoms-fall {
  0%   { background-position: left 0 top 0, right 0 bottom 0, 0 0, 0 0; }
  100% { background-position: left 0 top 0, right 0 bottom 0, -220px 440px, 0 0; }
}

/* Кисть ведёт мазок слева направо, потом лист «высыхает» и всё сначала */
@keyframes blossoms-brush {
  0%   { background-position: 100% 0, left 0 bottom 4px; }
  70%  { background-position: 0% 0, left 0 bottom 4px; }
  100% { background-position: 0% 0, left 0 bottom 4px; }
}

/* ---------- Типографика ---------- */
.tavo-bubble-content,
.tavo-speaker-name,
.tavo-composer-input {
  font-family: "Lora", "Noto Serif", Georgia, serif;
}

.tavo-message-content {
  line-height: 1.65;
}

.tavo-message-content::selection,
.tavo-message-content *::selection {
  background: rgba(200, 53, 43, 0.22);
  color: inherit;
}

/* ---------- Персонаж: лист рисовой бумаги ---------- */
.tavo-bubble {
  border-radius: 2px;
}

.tavo-character-bubble {
  background-color: #fbf6ea;
  background-image:
    url("theme/assets/corner-tl.svg"),
    url("theme/assets/corner-br.svg"),
    url("theme/assets/petals.png"),
    url("theme/assets/paper.png");
  background-size: 20px 20px, 20px 20px, 220px 220px, 256px 256px;
  background-repeat: no-repeat, no-repeat, repeat, repeat;
  background-position: left 0 top 0, right 0 bottom 0, 0 0, 0 0;
  border: 1px solid rgba(160, 60, 40, 0.16);
  box-shadow: 0 3px 12px rgba(80, 40, 20, 0.12);
  padding: 13px 18px;
  animation: blossoms-fall 60s linear infinite;
}

/* ---------- Вы: записка на розоватой бумаге ---------- */
.tavo-user-bubble {
  background-color: #f6e3d8;
  border-left: 3px solid #c8352b;
  box-shadow: 0 3px 12px rgba(80, 40, 20, 0.1);
}

/* ---------- Имена: маленькая красная печать перед именем ---------- */
.tavo-speaker-name {
  color: #8c2a20;
  font-weight: 600;
  letter-spacing: 0.06em;
}

.tavo-speaker-name::before {
  content: "";
  display: inline-block;
  width: 0.62em;
  height: 0.62em;
  margin-right: 0.45em;
  vertical-align: 0.05em;
  background: #c8352b;
  border-radius: 1px;
  box-shadow: inset 0 0 0 1.5px rgba(251, 246, 234, 0.75);
}

.tavo-avatar {
  outline: 1.5px solid rgba(200, 53, 43, 0.7);
  outline-offset: -1.5px;
}

/* ---------- Мысли, разделитель, вложения ---------- */
.tavo-message-reasoning {
  font-style: italic;
  color: #6b5a4a;
  border-left: 1px dashed rgba(43, 33, 24, 0.35);
  padding-left: 10px;
}

.tavo-message-divider {
  height: 32px;
  border: 0;
  background: url("theme/assets/divider.svg") center / min(320px, 76%) auto no-repeat;
}

.tavo-message-attachments {
  outline: 4px solid #fbf6ea;
  box-shadow: 0 3px 12px rgba(80, 40, 20, 0.18);
}

.tavo-action-bar-button,
.tavo-action-bar-button-group {
  background-color: rgba(251, 246, 234, 0.85);
  border-radius: 2px;
}

/* ---------- Поле ввода: лист под кистью ---------- */
.tavo-composer-shell {
  background-color: rgba(246, 239, 225, 0.97);
  border: 1px solid rgba(140, 42, 32, 0.45);
  border-radius: 3px;
  box-shadow: 0 3px 12px rgba(0, 0, 0, 0.25);
}

/* Пока персонаж отвечает, кисть выводит мазок тушью под строкой */
:root:has(.tavo-composer-stop-icon) .tavo-composer-shell {
  background-image:
    linear-gradient(90deg, rgba(246, 239, 225, 0) 0 46%, rgba(246, 239, 225, 0.97) 54% 100%),
    url("theme/assets/brush.png");
  background-size: 220% 100%, 100% 22px;
  background-repeat: no-repeat, no-repeat;
  animation: blossoms-brush 4.5s ease-in-out infinite;
}

.tavo-composer-input {
  color: #2b2118;
  caret-color: #c8352b;
}

.tavo-composer-input::placeholder {
  color: #9c8a76;
  font-style: italic;
}

@media (prefers-reduced-motion: reduce) {
  .tavo-character-bubble,
  :root:has(.tavo-composer-stop-icon) .tavo-composer-shell {
    animation: none;
  }
}
